turret, barrel, base, flare1 = piece('turret', 'barrel', 'base', 'flare1')

local rad = math.rad
local COB2RAD = math.pi / 32768
local SIG_AIM = 1
local restore_delay = 0

local function RestoreAfterDelay()
	Sleep(restore_delay)
	Turn(turret, y_axis, 0, rad(35))
	Turn(barrel, x_axis, 0, rad(15))
end

local function SetMaxReloadTime(reload)
	restore_delay = reload * 2
end

function script.Create()
	StartThread(SmokeUnit, { turret })  -- damage smoke
	restore_delay = 3000
	SetMaxReloadTime(Spring.UnitScript.GetLongestReloadTime(unitID))
end

function script.SweetSpot()
	return base
end

function script.AimFromWeapon(num)
	return turret
end

function script.QueryWeapon(num)
	return flare1
end

function script.AimWeapon(num, heading, pitch)
	Signal(SIG_AIM)
	SetSignalMask(SIG_AIM)
	Turn(turret, y_axis, heading, rad(35))
	Turn(barrel, x_axis, -pitch, rad(15))
	WaitForTurn(turret, y_axis)
	WaitForTurn(barrel, x_axis)
	StartThread(RestoreAfterDelay)
	return true
end

function script.FireWeapon(num)
	Move(barrel, z_axis, -6, 1250)
	Sleep(150)
	WaitForMove(barrel, z_axis)
	Move(barrel, z_axis, 0, 7.5)
end

local function HitByWeapon(x, z)
	local anglex, anglez = 500 * z, 500 * x
	Turn(base, z_axis, -(anglez * COB2RAD), rad(105))
	Turn(base, x_axis, anglex * COB2RAD, rad(105))
	WaitForTurn(base, z_axis)
	WaitForTurn(base, x_axis)
	Turn(base, z_axis, 0, rad(30))
	Turn(base, x_axis, 0, rad(30))
end

function script.HitByWeapon(x, z)
	StartThread(HitByWeapon, x, z)
end

function script.RockUnit(x, z)
	local anglex, anglez = 500 * z, 500 * x
	Turn(base, x_axis, anglex * COB2RAD, rad(50))
	Turn(base, z_axis, -(anglez * COB2RAD), rad(50))
	WaitForTurn(base, z_axis)
	WaitForTurn(base, x_axis)
	Turn(base, z_axis, 0, rad(20))
	Turn(base, x_axis, 0, rad(20))
end

function script.Killed(recentDamage, maxHealth)
	local severity = recentDamage / maxHealth * 100
	if severity <= 25 then
		Explode(barrel, SFX.NONE + SFX.NO_HEATCLOUD)
		Explode(base, SFX.NONE)
		Explode(flare1, SFX.NONE + SFX.NO_HEATCLOUD)
		Explode(turret, SFX.NONE)
		return 1
	end
	if severity <= 50 then
		Explode(barrel, SFX.FALL + SFX.NO_HEATCLOUD)
		Explode(base, SFX.NONE)
		Explode(flare1, SFX.FALL + SFX.NO_HEATCLOUD)
		Explode(turret, SFX.SHATTER)
		return 2
	end
	if severity <= 99 then
		Explode(barrel, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Explode(base, SFX.NONE)
		Explode(flare1, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Explode(turret, SFX.SHATTER)
		return 2
	end
	Explode(barrel, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
	Explode(base, SFX.NONE)
	Explode(flare1, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
	Explode(turret, SFX.SHATTER + SFX.EXPLODE_ON_HIT)
	return 2
end
